
export function warn(msg: string): void {
  if (typeof console!=='undefined' && console.warn && typeof process !== 'undefined' && process.env && process.env.NODE_ENV !== 'production') { // eslint-disable-line
    console.warn(`[global-string-format] Warn: ${msg}`); // eslint-disable-line
  }
}
export function error(msg: string): void {
  if (typeof console!=='undefined' && console.error && typeof process !== 'undefined' && process.env &&  process.env.NODE_ENV !== 'production') { // eslint-disable-line
    console.error(`[global-string-format] Error: ${msg}`); // eslint-disable-line
  }
}